{
  "name": "tinker-exercise-api-design",
  "version": "0.2.0",
  "private": true,
  "description": "Practice: write OpenAPI YAML by hand, one step at a time",
  "type": "module",
  "scripts": {
    "lint": "node scripts/check-step.mjs --all-solutions",
    "check:step": "node scripts/check-step.mjs",
    "check:solutions": "node scripts/check-step.mjs --all-solutions",
    "check": "npm run check:solutions"
  },
  "engines": {
    "node": ">=20"
  },
  "devDependencies": {
    "@redocly/cli": "^1.34.3",
    "yaml": "^2.7.1"
  }
}

#!/usr/bin/env node
/**
 * Lint and assert required OpenAPI shapes for one step.
 *
 * Usage:
 *   node scripts/check-step.mjs 03
 *   node scripts/check-step.mjs 03 --solutions
 *   node scripts/check-step.mjs --all-solutions
 */
import { spawnSync } from "node:child_process";
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import YAML from "yaml";

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const ROOT = path.resolve(__dirname, "..");

const STEPS = {
  "01": "01-smallest-valid-spec",
  "02": "02-name-the-thing",
  "03": "03-create",
  "04": "04-failure",
  "05": "05-lists",
  "06": "06-auth",
  "07": "07-from-scratch",
};

/** Step 00 is plain English only; no machine check. */
const NO_CHECK_STEPS = new Set(["00"]);

function fail(message) {
  console.error(`check:step: ${message}`);
  process.exit(1);
}

function loadSpec(filePath) {
  if (!fs.existsSync(filePath)) {
    fail(`missing file ${filePath}`);
  }
  const raw = fs.readFileSync(filePath, "utf8");
  const stripped = raw
    .split("\n")
    .filter((line) => !/^\s*#/.test(line))
    .join("\n")
    .trim();
  if (!stripped) {
    fail(`${filePath} is empty (comment-only files do not pass)`);
  }
  try {
    return YAML.parse(raw);
  } catch (err) {
    fail(`YAML parse failed for ${filePath}: ${err.message}`);
  }
}

function get(obj, dotted) {
  return dotted.split(".").reduce((acc, key) => (acc == null ? acc : acc[key]), obj);
}

function assert(condition, message) {
  if (!condition) fail(message);
}

function hasQueryParam(operation, name) {
  const params = operation?.parameters ?? [];
  return params.some((p) => p && p.name === name && p.in === "query");
}

function responseUsesRef(operation, status, refSuffix) {
  const content = operation?.responses?.[status]?.content?.["application/json"];
  const ref = content?.schema?.$ref;
  return typeof ref === "string" && ref.endsWith(refSuffix);
}

function lintFile(filePath) {
  const result = spawnSync(
    "npx",
    ["--no-install", "@redocly/cli", "lint", filePath, "--config", "redocly.yaml"],
    { cwd: ROOT, encoding: "utf8", stdio: ["ignore", "pipe", "pipe"] }
  );
  if (result.status !== 0) {
    process.stdout.write(result.stdout || "");
    process.stderr.write(result.stderr || "");
    fail(`@redocly/cli lint failed for ${filePath}`);
  }
}

function checkStep01(spec) {
  assert(typeof spec.openapi === "string" && spec.openapi.startsWith("3."), "openapi version 3.x required");
  assert(typeof spec.info?.title === "string" && spec.info.title.length > 0, "info.title required");
  assert(typeof spec.info?.version === "string" && spec.info.version.length > 0, "info.version required");
  const getIntent = get(spec, "paths./payment_intents/{id}.get");
  assert(getIntent, "GET /payment_intents/{id} required");
  assert(getIntent.responses?.["200"], "GET /payment_intents/{id} must declare 200");
}

function checkStep02(spec) {
  checkStep01(spec);
  const intent = get(spec, "components.schemas.PaymentIntent");
  assert(intent && intent.type === "object", "components.schemas.PaymentIntent required");
  assert(
    responseUsesRef(get(spec, "paths./payment_intents/{id}.get"), "200", "/PaymentIntent"),
    "GET /payment_intents/{id} 200 must $ref PaymentIntent"
  );
}

function checkStep03(spec) {
  checkStep02(spec);
  const post = get(spec, "paths./payment_intents.post");
  assert(post, "POST /payment_intents required");
  assert(post.requestBody, "POST /payment_intents requestBody required");
  const create = get(spec, "components.schemas.CreatePaymentIntent")
    ?? Object.values(spec.components?.schemas ?? {}).find(
      (s) => Array.isArray(s?.required) && s.required.length > 0 && s !== get(spec, "components.schemas.PaymentIntent")
    );
  assert(create, "a create schema with required fields is required");
  assert(Array.isArray(create.required) && create.required.length > 0, "create schema must list required fields");
  const bodySchema = post.requestBody?.content?.["application/json"]?.schema;
  assert(bodySchema, "POST /payment_intents must accept application/json");
}

function checkStep04(spec) {
  checkStep03(spec);
  const error = get(spec, "components.schemas.Error");
  assert(error && error.type === "object", "components.schemas.Error required");
  const getIntent = get(spec, "paths./payment_intents/{id}.get");
  const post = get(spec, "paths./payment_intents.post");
  assert(getIntent.responses?.["404"] || post.responses?.["404"], "a 404 response is required");
  assert(getIntent.responses?.["400"] || post.responses?.["400"], "a 400 response is required");
  const usesError =
    responseUsesRef(getIntent, "404", "/Error") ||
    responseUsesRef(getIntent, "400", "/Error") ||
    responseUsesRef(post, "404", "/Error") ||
    responseUsesRef(post, "400", "/Error");
  assert(usesError, "400 or 404 must $ref Error");
}

function checkStep05(spec) {
  checkStep04(spec);
  const list = get(spec, "paths./payment_intents.get");
  assert(list, "GET /payment_intents required");
  assert(list.responses?.["200"], "GET /payment_intents must declare 200");
  const hasLimit = hasQueryParam(list, "limit");
  const hasOffset = hasQueryParam(list, "offset");
  const hasPage = hasQueryParam(list, "page");
  const hasCursor = hasQueryParam(list, "cursor");
  assert(
    (hasLimit && hasOffset) || hasPage || hasCursor || hasLimit,
    "GET /payment_intents needs pagination query params (limit/offset, page, or cursor)"
  );
}

function checkStep06(spec) {
  checkStep05(spec);
  const schemes = spec.components?.securitySchemes;
  assert(schemes && Object.keys(schemes).length > 0, "components.securitySchemes required");
  const rootSecurity = Array.isArray(spec.security) && spec.security.length > 0;
  const opSecurity = [
    "paths./payment_intents.get",
    "paths./payment_intents.post",
    "paths./payment_intents/{id}.get",
  ].some((p) => {
    const op = get(spec, p);
    return Array.isArray(op?.security) && op.security.length > 0;
  });
  assert(rootSecurity || opSecurity, "security must be applied at root or on an operation");
}

function checkStep07(spec) {
  assert(typeof spec.openapi === "string" && spec.openapi.startsWith("3."), "openapi version 3.x required");
  assert(typeof spec.info?.title === "string" && spec.info.title.length > 0, "info.title required");
  assert(typeof spec.info?.version === "string" && spec.info.version.length > 0, "info.version required");

  assert(get(spec, "paths./payment_intents.post"), "POST /payment_intents required");
  assert(get(spec, "paths./payment_intents.get"), "GET /payment_intents required");
  assert(get(spec, "paths./payment_intents/{paymentIntentId}.get"), "GET /payment_intents/{paymentIntentId} required");
  assert(
    get(spec, "paths./payment_intents/{paymentIntentId}/capture.post"),
    "POST /payment_intents/{paymentIntentId}/capture required"
  );
  assert(
    get(spec, "paths./payment_intents/{paymentIntentId}/refunds.post"),
    "POST /payment_intents/{paymentIntentId}/refunds required"
  );
  assert(get(spec, "paths./refunds/{refundId}.get"), "GET /refunds/{refundId} required");
  assert(get(spec, "paths./events/{eventId}.get"), "GET /events/{eventId} required");

  for (const name of ["PaymentIntent", "Capture", "Refund", "WebhookEvent", "Error"]) {
    assert(get(spec, `components.schemas.${name}`), `components.schemas.${name} required`);
  }

  const createIntent = get(spec, "paths./payment_intents.post");
  assert(createIntent.requestBody, "POST /payment_intents requestBody required");
  assert(
    createIntent.responses?.["201"] || createIntent.responses?.["200"],
    "POST /payment_intents success response required"
  );
  assert(createIntent.responses?.["400"], "POST /payment_intents 400 required");
  assert(
    get(spec, "paths./payment_intents/{paymentIntentId}.get").responses?.["404"],
    "GET payment intent 404 required"
  );
}

const CHECKERS = {
  "01": checkStep01,
  "02": checkStep02,
  "03": checkStep03,
  "04": checkStep04,
  "05": checkStep05,
  "06": checkStep06,
  "07": checkStep07,
};

function resolveStepId(raw) {
  const cleaned = String(raw).replace(/^0+/, "") || "0";
  const padded = cleaned.padStart(2, "0");
  if (!STEPS[padded] && !NO_CHECK_STEPS.has(padded)) {
    fail(`unknown step "${raw}". Use 00..07`);
  }
  return padded;
}

function checkOne(stepId, useSolutions) {
  const folder = STEPS[stepId];
  const filePath = useSolutions
    ? path.join(ROOT, "solutions", folder, "openapi.yaml")
    : path.join(ROOT, folder, "openapi.yaml");
  console.log(`check:step ${stepId} -> ${path.relative(ROOT, filePath)}`);
  const spec = loadSpec(filePath);
  lintFile(filePath);
  CHECKERS[stepId](spec);
  console.log(`ok: step ${stepId}`);
}

function main() {
  const args = process.argv.slice(2).filter((a) => a !== "--");
  const useSolutions = args.includes("--solutions");
  const allSolutions = args.includes("--all-solutions");
  const positional = args.filter((a) => !a.startsWith("--"));

  if (allSolutions) {
    for (const stepId of Object.keys(STEPS)) {
      checkOne(stepId, true);
    }
    console.log("ok: all solutions");
    return;
  }

  if (positional.length !== 1) {
    fail("usage: npm run check:step -- <01-07> [--solutions]");
  }

  checkOne(resolveStepId(positional[0]), useSolutions);
}

main();

/**
 * Baseline: AI SDK-shaped agent + MCP-shaped tools, but a global mutex.
 * Only one request runs at a time. Under concurrent load, wait times explode.
 *
 * Stub LLM and in-process tools. No network. No API keys.
 */

const ORDERS = {
  ord_100: { id: "ord_100", status: "paid", amount_cents: 4200 },
  ord_200: { id: "ord_200", status: "refunded", amount_cents: 1500 },
};

/** MCP-shaped tool list / call (in-process stand-in). */
const mcpTools = {
  async listTools() {
    return ["lookup_order", "search_docs"];
  },
  async callTool(name, args) {
    await sleep(25);
    if (name === "lookup_order") return ORDERS[args.orderId] || { error: "not_found" };
    if (name === "search_docs") {
      return {
        snippet: String(args.query || "").toLowerCase().includes("refund")
          ? "Refunds take 3 to 5 business days."
          : "No doc match.",
      };
    }
    throw new Error("unknown tool: " + name);
  },
};

/** Stub "model": pick a tool from the prompt (AI SDK generateText stand-in). */
export function chooseTool(prompt) {
  const order = String(prompt).match(/\bord_[a-z0-9]+\b/i);
  if (order) return { name: "lookup_order", args: { orderId: order[0] } };
  return { name: "search_docs", args: { query: String(prompt) } };
}

let chain = Promise.resolve();

export async function runAgent(prompt) {
  const run = chain.then(async () => {
    await sleep(15); // stub model think
    const pick = chooseTool(prompt);
    const toolResult = await mcpTools.callTool(pick.name, pick.args);
    return { tool: pick.name, toolResult, mode: "serial" };
  });
  chain = run.then(
    () => undefined,
    () => undefined
  );
  return run;
}

export async function runMany(prompts) {
  const t0 = performance.now();
  const results = [];
  for (const prompt of prompts) {
    results.push(await runAgent(prompt));
  }
  return { results, ms: performance.now() - t0, mode: "serial" };
}

function sleep(ms) {
  return new Promise((r) => setTimeout(r, ms));
}

/**
 * Better: same stub LLM + MCP tools, but a concurrent job queue, light rate
 * limit, and response cache. Evals can run in parallel.
 *
 * Diff against baseline.js. Target shape for the 45-minute core change.
 */

const ORDERS = {
  ord_100: { id: "ord_100", status: "paid", amount_cents: 4200 },
  ord_200: { id: "ord_200", status: "refunded", amount_cents: 1500 },
};

const mcpTools = {
  async listTools() {
    return ["lookup_order", "search_docs"];
  },
  async callTool(name, args) {
    await sleep(25);
    if (name === "lookup_order") return ORDERS[args.orderId] || { error: "not_found" };
    if (name === "search_docs") {
      return {
        snippet: String(args.query || "").toLowerCase().includes("refund")
          ? "Refunds take 3 to 5 business days."
          : "No doc match.",
      };
    }
    throw new Error("unknown tool: " + name);
  },
};

export function chooseTool(prompt) {
  const order = String(prompt).match(/\bord_[a-z0-9]+\b/i);
  if (order) return { name: "lookup_order", args: { orderId: order[0] } };
  return { name: "search_docs", args: { query: String(prompt) } };
}

export function createQueue({ concurrency = 4, minIntervalMs = 5, cacheTtlMs = 15_000 } = {}) {
  const q = [];
  let active = 0;
  let nextSlot = 0;
  const cache = new Map();
  const stats = { enqueued: 0, completed: 0, cacheHits: 0, cacheMisses: 0 };

  function pump() {
    while (active < concurrency && q.length) {
      const job = q.shift();
      active += 1;
      const wait = Math.max(0, nextSlot - Date.now());
      nextSlot = Date.now() + wait + minIntervalMs;
      Promise.resolve()
        .then(() => sleep(wait))
        .then(() => job.work())
        .then(job.resolve, job.reject)
        .finally(() => {
          active -= 1;
          stats.completed += 1;
          pump();
        });
    }
  }

  function enqueue(key, work) {
    stats.enqueued += 1;
    const hit = cache.get(key);
    if (hit && hit.expires > Date.now()) {
      stats.cacheHits += 1;
      return Promise.resolve({ ...hit.value, cache: true });
    }
    stats.cacheMisses += 1;
    return new Promise((resolve, reject) => {
      q.push({
        resolve: (value) => {
          cache.set(key, { value, expires: Date.now() + cacheTtlMs });
          resolve({ ...value, cache: false });
        },
        reject,
        work,
      });
      pump();
    });
  }

  return { enqueue, stats: () => ({ ...stats, active, queued: q.length }) };
}

const queue = createQueue({ concurrency: 4 });

export async function runAgent(prompt) {
  return queue.enqueue(prompt, async () => {
    await sleep(15);
    const pick = chooseTool(prompt);
    const toolResult = await mcpTools.callTool(pick.name, pick.args);
    return { tool: pick.name, toolResult, mode: "queued" };
  });
}

export async function runMany(prompts) {
  const t0 = performance.now();
  const results = await Promise.all(prompts.map((p) => runAgent(p)));
  return {
    results,
    ms: performance.now() - t0,
    mode: "queued",
    queue: queue.stats(),
  };
}

/** Parallel evals: tool-choice cases run with a small worker pool. */
export async function runEvals() {
  const cases = [
    { prompt: "What is the status of order ord_100?", expect: "lookup_order" },
    { prompt: "Is ord_200 refunded already?", expect: "lookup_order" },
    { prompt: "Customer asks for a refund policy blurb", expect: "search_docs" },
    { prompt: "lookup ord_100 please", expect: "lookup_order" },
    { prompt: "Where are refund docs?", expect: "search_docs" },
    { prompt: "status for ord_200", expect: "lookup_order" },
  ];

  const t0 = performance.now();
  const results = await mapPool(cases, 4, async (c) => {
    const pick = chooseTool(c.prompt);
    if (pick.name !== c.expect) {
      throw new Error(`eval fail: ${c.prompt} -> ${pick.name}, want ${c.expect}`);
    }
    return c.expect;
  });
  return { passed: results.length, ms: performance.now() - t0 };
}

async function mapPool(items, concurrency, fn) {
  const out = new Array(items.length);
  let i = 0;
  async function worker() {
    while (i < items.length) {
      const idx = i;
      i += 1;
      out[idx] = await fn(items[idx], idx);
    }
  }
  await Promise.all(Array.from({ length: concurrency }, () => worker()));
  return out;
}

function sleep(ms) {
  return new Promise((r) => setTimeout(r, ms));
}

/**
 * Timing + assert harness: concurrent prompts and tool-choice evals.
 * Better must finish the batch faster and pass evals.
 */
import assert from "node:assert/strict";
import * as baseline from "./baseline.js";
import * as better from "./better.js";

const prompts = [
  "What is the status of order ord_100?",
  "Is ord_200 refunded already?",
  "Customer asks for a refund policy blurb",
  "lookup ord_100 please",
  "Where are refund docs?",
  "status for ord_200",
  "What is the status of order ord_100?",
  "Is ord_200 refunded already?",
];

const base = await baseline.runMany(prompts);
const nice = await better.runMany(prompts);
const evals = await better.runEvals();

console.log("baseline_ms=", base.ms.toFixed(1), "mode=", base.mode);
console.log("better_ms=", nice.ms.toFixed(1), "mode=", nice.mode, "queue=", nice.queue);
console.log("evals_passed=", evals.passed, "evals_ms=", evals.ms.toFixed(1));

assert.equal(nice.results.length, prompts.length);
assert.equal(base.results.length, prompts.length);
assert.ok(nice.ms < base.ms, `better should be faster (${nice.ms} vs ${base.ms})`);
assert.equal(evals.passed, 6);
assert.ok(
  nice.results.every((r) => r.tool === "lookup_order" || r.tool === "search_docs")
);

console.log("pass");

{
  "name": "vercel-ai-mcp-exercise",
  "private": true,
  "type": "module",
  "scripts": { "check": "node check.mjs" }
}

/**
 * Baseline: Stripe-shaped webhooks processed inline.
 * Replays double-apply side effects. No idempotency ledger. No DLQ.
 *
 * Fake events only. No Stripe SDK, keys, or network.
 */

/** @type {string[]} */
export const sideEffects = [];

export function reset() {
  sideEffects.length = 0;
}

/** Simulate slow inline work (email / DB) on the request thread. */
export async function handleWebhook(event) {
  await sleep(12);
  sideEffects.push(`${event.id}:${event.type}`);
  return { received: true, applied: true };
}

/** Burst replay: deliver each event, then replay the same ids many times. */
export async function burstReplay(events, replays = 5) {
  reset();
  for (const event of events) await handleWebhook(event);
  const jobs = [];
  for (let r = 0; r < replays; r += 1) {
    for (const event of events) jobs.push(handleWebhook(event));
  }
  await Promise.all(jobs);
  const unique = new Set(events.map((e) => e.id)).size;
  return {
    mode: "baseline",
    unique_events: unique,
    side_effects: sideEffects.length,
    duplicates_applied: Math.max(0, sideEffects.length - unique),
  };
}

function sleep(ms) {
  return new Promise((r) => setTimeout(r, ms));
}

/**
 * Better: accept webhooks into a small in-memory queue with an idempotency
 * ledger keyed by Stripe event id, retries, and a dead-letter queue.
 *
 * Diff against baseline.js. Fake events only.
 */

/** @type {string[]} */
export const sideEffects = [];
/** @type {{ event: object, error: string }[]} */
export const dlq = [];

const ledger = new Map(); // eventId -> applied | inflight
const stats = {
  enqueued: 0,
  applied: 0,
  duplicates: 0,
  retries: 0,
  deadLettered: 0,
};

export function reset() {
  sideEffects.length = 0;
  dlq.length = 0;
  ledger.clear();
  stats.enqueued = 0;
  stats.applied = 0;
  stats.duplicates = 0;
  stats.retries = 0;
  stats.deadLettered = 0;
}

async function apply(event) {
  await sleep(12);
  sideEffects.push(`${event.id}:${event.type}`);
}

/**
 * Process one event with idempotency + retries.
 * Poison events (type === "poison.test") fail until DLQ.
 */
export async function handleWebhook(event, { maxAttempts = 3 } = {}) {
  stats.enqueued += 1;
  if (ledger.get(event.id) === "applied" || ledger.get(event.id) === "inflight") {
    stats.duplicates += 1;
    return { received: true, applied: false, duplicate: true };
  }

  let attempts = 0;
  while (attempts < maxAttempts) {
    attempts += 1;
    ledger.set(event.id, "inflight");
    try {
      if (event.type === "poison.test") throw new Error("poison message");
      await apply(event);
      ledger.set(event.id, "applied");
      stats.applied += 1;
      return { received: true, applied: true, duplicate: false };
    } catch (err) {
      ledger.delete(event.id);
      stats.retries += 1;
      if (attempts >= maxAttempts) {
        dlq.push({ event, error: String(err.message || err) });
        stats.deadLettered += 1;
        return { received: true, applied: false, dlq: true };
      }
    }
  }
  return { received: true, applied: false };
}

export async function burstReplay(events, replays = 5) {
  reset();
  for (const event of events) await handleWebhook(event);
  const jobs = [];
  for (let r = 0; r < replays; r += 1) {
    for (const event of events) jobs.push(handleWebhook(event));
  }
  await Promise.all(jobs);
  const unique = new Set(events.map((e) => e.id)).size;
  return {
    mode: "better",
    unique_events: unique,
    side_effects: sideEffects.length,
    duplicates_applied: Math.max(0, sideEffects.length - unique),
    stats: { ...stats },
    dlq: dlq.length,
  };
}

/** Stretch helper: agent-safe create requires an idempotency key. */
export function createPaymentIntent({ amount, currency, idempotencyKey }) {
  if (!idempotencyKey) {
    return {
      ok: false,
      error: { code: "idempotency_key_required" },
    };
  }
  return {
    ok: true,
    payment_intent: {
      id: "pi_test_" + String(idempotencyKey).slice(0, 8),
      amount: amount || 500,
      currency: currency || "usd",
      mode: "test",
    },
  };
}

function sleep(ms) {
  return new Promise((r) => setTimeout(r, ms));
}

/**
 * Burst-replay harness: baseline double-applies; better must not.
 * Also checks DLQ for a poison event.
 */
import assert from "node:assert/strict";
import * as baseline from "./baseline.js";
import * as better from "./better.js";

const events = Array.from({ length: 12 }, (_, i) => ({
  id: `evt_${i + 1}`,
  type: "payment_intent.succeeded",
  data: { object: { id: `pi_${i + 1}` } },
}));

const base = await baseline.burstReplay(events, 4);
const nice = await better.burstReplay(events, 4);

better.reset();
const poison = await better.handleWebhook({ id: "evt_poison", type: "poison.test" });

console.log("baseline=", base);
console.log("better=", nice);
console.log("poison=", poison, "dlq=", better.dlq.length);

assert.ok(base.duplicates_applied > 0, "baseline should double-apply on replay");
assert.equal(nice.duplicates_applied, 0, "better must not double-apply");
assert.equal(nice.side_effects, nice.unique_events);
assert.equal(poison.dlq, true);
assert.equal(better.dlq.length, 1);

const missingKey = better.createPaymentIntent({ amount: 500 });
assert.equal(missingKey.ok, false);
